  ComAtprotoSyncSubscribeRepos: {
    lexicon: 1,
    id: "com.atproto.sync.subscribeRepos",
    defs: {
      main: {
        type: "subscription",
        description: "Subscribe to repo updates",
        parameters: {
          type: "params",
          properties: {
            cursor: {
              type: "integer",
              description: "The last known event to backfill from."
            }
          }
        },
        message: {
          schema: {
            type: "union",
            refs: [
              "lex:com.atproto.sync.subscribeRepos#commit",
              "lex:com.atproto.sync.subscribeRepos#handle",
              "lex:com.atproto.sync.subscribeRepos#migrate",
              "lex:com.atproto.sync.subscribeRepos#tombstone",
              "lex:com.atproto.sync.subscribeRepos#info"
            ]
          }
        },
        errors: [
          {
            name: "FutureCursor"
          },
          {
            name: "ConsumerTooSlow"
          }
        ]
      },
      commit: {
        type: "object",
        required: [
          "seq",
          "rebase",
          "tooBig",
          "repo",
          "commit",
          "rev",
          "since",
          "blocks",
          "ops",
          "blobs",
          "time"
        ],
        nullable: ["prev", "since"],
        properties: {
          seq: {
            type: "integer"
          },
          rebase: {
            type: "boolean"
          },
          tooBig: {
            type: "boolean"
          },
          repo: {
            type: "string",
            format: "did"
          },
          commit: {
            type: "cid-link"
          },
          prev: {
            type: "cid-link"
          },
          rev: {
            type: "string",
            description: "The rev of the emitted commit"
          },
          since: {
            type: "string",
            description: "The rev of the last emitted commit from this repo"
          },
          blocks: {
            type: "bytes",
            description: "CAR file containing relevant blocks",
            maxLength: 1e6
          },
          ops: {
            type: "array",
            items: {
              type: "ref",
              ref: "lex:com.atproto.sync.subscribeRepos#repoOp"
            },
            maxLength: 200
          },
          blobs: {
            type: "array",
            items: {
              type: "cid-link"
            }
          },
          time: {
            type: "string",
            format: "datetime"
          }
        }
      },
      handle: {
        type: "object",
        required: ["seq", "did", "handle", "time"],
        properties: {
          seq: {
            type: "integer"
          },
          did: {
            type: "string",
            format: "did"
          },
          handle: {
            type: "string",
            format: "handle"
          },
          time: {
            type: "string",
            format: "datetime"
          }
        }
      },
      migrate: {
        type: "object",
        required: ["seq", "did", "migrateTo", "time"],
        nullable: ["migrateTo"],
        properties: {
          seq: {
            type: "integer"
          },
          did: {
            type: "string",
            format: "did"
          },
          migrateTo: {
            type: "string"
          },
          time: {
            type: "string",
            format: "datetime"
          }
        }
      },
      tombstone: {
        type: "object",
        required: ["seq", "did", "time"],
        properties: {
          seq: {
            type: "integer"
          },
          did: {
            type: "string",
            format: "did"
          },
          time: {
            type: "string",
            format: "datetime"
          }
        }
      },
      info: {
        type: "object",
        required: ["name"],
        properties: {
          name: {
            type: "string",
            knownValues: ["OutdatedCursor"]
          },
          message: {
            type: "string"
          }
        }
      },
      repoOp: {
        type: "object",
        description: "A repo operation, ie a write of a single record. For creates and updates, cid is the record's CID as of this operation. For deletes, it's null.",
        required: ["action", "path", "cid"],
        nullable: ["cid"],
        properties: {
          action: {
            type: "string",
            knownValues: ["create", "update", "delete"]
          },
          path: {
            type: "string"
          },
          cid: {
            type: "cid-link"
          }
        }
      }
    }
  },
